import React, { useEffect, useMemo, useState } from "react";
import {
  Box,
  Button,
  Collapse,
  IconButton,
  InputAdornment,
  TextField,
  Typography,
} from "@mui/material";
import CancelIcon from "@mui/icons-material/Cancel";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import InfoOutlinedIcon from "@mui/icons-material/InfoOutlined";
import LockOutlinedIcon from "@mui/icons-material/LockOutlined";
import PhoneIphoneIcon from "@mui/icons-material/PhoneIphone";
import ReceiptLongOutlinedIcon from "@mui/icons-material/ReceiptLongOutlined";
import SearchIcon from "@mui/icons-material/Search";
import SignalCellularAltIcon from "@mui/icons-material/SignalCellularAlt";

/* ---------- design tokens (aligned with the BankMudraa dashboard) ---------- */
const BRAND = "#1e56e0";
const BRAND_DARK = "#1745b8";
const BRAND_SOFT = "#eaf1ff";
const BRAND_RING = "rgba(30,86,224,0.16)";
const ACCENT = "#f5a623"; // selected outline, same as the "Most used" tile
const INK = "#0f1f3d";
const MUTED = "#5f6f8c";
const FAINT = "#94a3b8";
const LINE = "#dfe7f5";
const FONT = "'Inter', 'Segoe UI', Arial, sans-serif";

// Indian mobile numbers: 10 digits, starting 6-9
const VALID_MOBILE = /^[6-9]\d{9}$/;

// smallest recharge the user can enter (backend commission slots must cover
// the range you allow here, otherwise payBBPSBill answers "No charges found!")
const MIN_AMOUNT = 10;
const QUICK_AMOUNTS = [49, 99, 199, 299, 499];

// show a search box above the operator tiles when the list is long
const OPERATOR_SEARCH_FROM = 8;

const SOFT_SHADOW = "0 6px 18px rgba(30,86,224,0.08)";

const panelSx = {
  background: "rgba(255,255,255,0.9)",
  backdropFilter: "blur(10px)",
  border: "1px solid rgba(255,255,255,0.95)",
  borderRadius: "24px",
  boxShadow: "0 12px 34px rgba(30,86,224,0.12)",
  p: { xs: 2, sm: 3 },
  minWidth: 0,
};

const fieldSx = {
  "& .MuiOutlinedInput-root": {
    borderRadius: "16px",
    backgroundColor: "#fff",
    fontFamily: FONT,
    fontWeight: 600,
    fontSize: 15,
    boxShadow: SOFT_SHADOW,
    "& fieldset": { borderColor: LINE },
    "&:hover fieldset": { borderColor: "#b9c8e8" },
    "&.Mui-focused": { boxShadow: `0 0 0 4px ${BRAND_RING}` },
    "&.Mui-focused fieldset": { borderColor: BRAND, borderWidth: "1.5px" },
  },
  "& input::placeholder": { color: FAINT, opacity: 1, fontWeight: 500 },
};

/* header used by every section: icon chip + title + optional right side */
const PanelHead = ({ icon, title, right }) => (
  <Box sx={{ display: "flex", alignItems: "center", gap: 1.4, mb: 2 }}>
    <Box
      sx={{
        width: 38,
        height: 38,
        borderRadius: "12px",
        backgroundColor: BRAND_SOFT,
        color: BRAND,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        flexShrink: 0,
        fontFamily: FONT,
        fontWeight: 800,
        fontSize: 19,
      }}
    >
      {icon}
    </Box>
    <Typography sx={{ fontFamily: FONT, fontWeight: 800, fontSize: 18, color: INK, flex: 1 }}>
      {title}
    </Typography>
    {right}
  </Box>
);

/* tinted info tile, same idea as the wallet tiles on the dashboard */
const TINTS = {
  blue: { bg: "linear-gradient(135deg,#eef4ff,#e1ecff)", border: "#b6cdfb" },
  green: { bg: "linear-gradient(135deg,#ecfbf3,#d9f7e7)", border: "#7fe0b0" },
};

const InfoTile = ({ tint, label, value, logo }) => (
  <Box
    sx={{
      display: "flex",
      alignItems: "center",
      gap: 1.4,
      p: 1.6,
      borderRadius: "16px",
      background: TINTS[tint].bg,
      border: `1.5px solid ${TINTS[tint].border}`,
      minWidth: 0,
    }}
  >
    {logo && (
      <Box
        sx={{
          width: 38,
          height: 38,
          flexShrink: 0,
          borderRadius: "12px",
          backgroundColor: "#fff",
          border: `1px solid ${TINTS[tint].border}`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <img
          src={logo}
          alt=""
          width={24}
          height={24}
          style={{ objectFit: "contain" }}
          onError={(e) => {
            e.currentTarget.onerror = null;
            e.currentTarget.src = "/bbpslogo.png";
          }}
        />
      </Box>
    )}
    <Box sx={{ minWidth: 0 }}>
      <Typography sx={{ fontFamily: FONT, fontWeight: 600, fontSize: 12.5, color: MUTED }}>
        {label}
      </Typography>
      <Typography
        sx={{
          fontFamily: FONT,
          fontWeight: 800,
          fontSize: 16,
          color: INK,
          mt: 0.3,
          overflowWrap: "anywhere",
          fontVariantNumeric: "tabular-nums",
        }}
      >
        {value || "-"}
      </Typography>
    </Box>
  </Box>
);

/**
 * Mobile recharge flow (RealRobo backend):
 *   1. user types a 10-digit mobile number
 *   2. user picks the operator
 *   3. user enters the amount (quick chips available)
 *   4. summary + "Proceed to Secure Payment"
 *
 * The backend no longer returns plans for Mobile Recharge, detects no
 * operator from the number and needs no circle or bill enquiry, so this
 * card makes no API calls and asks for no location. It only keeps the
 * parent's state in sync through `onSelectionChange` and calls `onProceed`
 * when the user taps the pay button (the parent then opens the TPIN dialog).
 */
const MobileRechargeCard = ({
  operatorList = [],
  disabled = false,
  onSelectionChange,
  onProceed,
}) => {
  const [number, setNumber] = useState("");
  const [operator, setOperator] = useState(null);
  const [amount, setAmount] = useState("");
  const [opQuery, setOpQuery] = useState("");

  const numberValid = VALID_MOBILE.test(number);
  const numberInvalid = number.length === 10 && !numberValid;

  const amountNum = Number(amount);
  const amountValid = amount !== "" && amountNum >= MIN_AMOUNT;
  const amountTooLow = amount !== "" && amountNum < MIN_AMOUNT;

  const visibleOperators = useMemo(() => {
    const q = opQuery.trim().toLowerCase();
    if (!q) return operatorList;
    return operatorList.filter((o) => String(o?.name || "").toLowerCase().includes(q));
  }, [operatorList, opQuery]);

  /* ---------- keep parent state in sync ---------- */
  useEffect(() => {
    onSelectionChange?.({
      operator,
      mobile: numberValid ? number : "",
      amount: amountValid ? amount : "",
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [operator, number, numberValid, amount, amountValid]);

  const canProceed = numberValid && !!operator && amountValid && !disabled;

  const ctaLabel = canProceed
    ? "Proceed to Secure Payment"
    : !numberValid
    ? "Enter mobile number to continue"
    : !operator
    ? "Select your operator to continue"
    : "Enter amount to continue";

  return (
    <Box
      sx={{
        width: "100%",
        mx: "auto",
        my: 2,
        p: { xs: 1.5, sm: 2.5 },
        borderRadius: { xs: "24px", sm: "32px" },
        border: "1px solid rgba(255,255,255,0.8)",
        fontFamily: FONT,
        background:
          "radial-gradient(rgba(30,86,224,0.10) 1px, transparent 1.4px) 0 0 / 18px 18px, linear-gradient(180deg,#dce9ff 0%,#eef4ff 55%,#f6f9ff 100%)",
        "&, & *, & *::before, & *::after": { boxSizing: "border-box" },
      }}
    >
      <Box
        sx={{
          display: "grid",
          gridTemplateColumns: { xs: "1fr", lg: "minmax(0,1fr) 340px" },
          gap: 2.5,
          alignItems: "start",
        }}
      >
        {/* ================= LEFT: number, operator, amount ================= */}
        <Box sx={panelSx}>
          <PanelHead icon={<PhoneIphoneIcon />} title="Mobile recharge" />

          {/* ---- Step 1: mobile number ---- */}
          <TextField
            fullWidth
            value={number}
            onChange={(e) => setNumber(e.target.value.replace(/\D/g, "").slice(0, 10))}
            placeholder="Enter 10-digit mobile number"
            autoComplete="off"
            inputProps={{
              inputMode: "numeric",
              maxLength: 10,
              "aria-label": "Mobile number",
              style: {
                fontSize: 18,
                letterSpacing: "0.04em",
                fontVariantNumeric: "tabular-nums",
                padding: "16px 4px",
              },
            }}
            error={numberInvalid}
            helperText={
              numberInvalid ? "Enter a valid mobile number (starts with 6, 7, 8 or 9)" : ""
            }
            InputProps={{
              startAdornment: (
                <InputAdornment position="start" sx={{ mr: 1.2, ml: 0.8 }}>
                  <Box
                    sx={{
                      pr: 1.5,
                      borderRight: `1px solid ${LINE}`,
                      fontFamily: FONT,
                      fontWeight: 700,
                      fontSize: 16,
                      color: MUTED,
                    }}
                  >
                    +91
                  </Box>
                </InputAdornment>
              ),
              endAdornment: number ? (
                <InputAdornment position="end">
                  <IconButton
                    size="small"
                    aria-label="Clear number"
                    onClick={() => setNumber("")}
                    sx={{ color: FAINT, "&:hover": { color: MUTED } }}
                  >
                    <CancelIcon fontSize="small" />
                  </IconButton>
                </InputAdornment>
              ) : null,
            }}
            sx={fieldSx}
          />

          {/* ---- Step 2: operator ---- */}
          <Collapse in={numberValid} unmountOnExit>
            <Box sx={{ mt: 3.5 }}>
              <PanelHead
                icon={<SignalCellularAltIcon />}
                title="Select operator"
                right={
                  operator ? (
                    <Typography sx={{ fontFamily: FONT, fontWeight: 700, fontSize: 13.5, color: BRAND }}>
                      {operator.name}
                    </Typography>
                  ) : null
                }
              />

              {operatorList.length > OPERATOR_SEARCH_FROM && (
                <TextField
                  fullWidth
                  value={opQuery}
                  onChange={(e) => setOpQuery(e.target.value)}
                  placeholder="Search operator"
                  autoComplete="off"
                  inputProps={{ "aria-label": "Search operator" }}
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <SearchIcon sx={{ color: FAINT, fontSize: 20 }} />
                      </InputAdornment>
                    ),
                  }}
                  sx={{ ...fieldSx, mb: 1.8 }}
                />
              )}

              {operatorList.length === 0 ? (
                <Typography sx={{ fontFamily: FONT, fontWeight: 500, fontSize: 14, color: MUTED }}>
                  No operators available right now.
                </Typography>
              ) : visibleOperators.length === 0 ? (
                <Typography sx={{ fontFamily: FONT, fontWeight: 500, fontSize: 14, color: MUTED }}>
                  No operator matches &quot;{opQuery}&quot;.
                </Typography>
              ) : (
                <Box
                  sx={{
                    display: "grid",
                    gridTemplateColumns: "repeat(auto-fill, minmax(150px, 1fr))",
                    gap: 1.6,
                    maxHeight: 340,
                    overflowY: "auto",
                    pt: 1.4,
                    px: 0.5,
                    pb: 0.5,
                    mx: -0.5,
                  }}
                >
                  {visibleOperators.map((op) => {
                    const isSelected = operator?._id === op._id;
                    return (
                      <Box
                        key={op._id}
                        component="button"
                        type="button"
                        aria-pressed={isSelected}
                        onClick={() => setOperator(op)}
                        sx={{
                          position: "relative",
                          cursor: "pointer",
                          display: "flex",
                          alignItems: "center",
                          gap: 1.2,
                          p: 1.4,
                          textAlign: "left",
                          borderRadius: "16px",
                          border: `2px solid ${isSelected ? ACCENT : "transparent"}`,
                          backgroundColor: "#fff",
                          boxShadow: isSelected ? "0 10px 24px rgba(245,166,35,0.25)" : SOFT_SHADOW,
                          transition: "border-color .15s, box-shadow .15s, transform .15s",
                          "&:hover": { transform: "translateY(-2px)" },
                          "&:focus-visible": { outline: `2px solid ${BRAND}`, outlineOffset: 2 },
                        }}
                      >
                        <Box
                          sx={{
                            width: 40,
                            height: 40,
                            flexShrink: 0,
                            borderRadius: "12px",
                            backgroundColor: BRAND_SOFT,
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "center",
                          }}
                        >
                          <img
                            src={op?.logo_url}
                            alt=""
                            width={26}
                            height={26}
                            style={{ objectFit: "contain" }}
                            onError={(e) => {
                              e.currentTarget.onerror = null;
                              e.currentTarget.src = "/bbpslogo.png";
                            }}
                          />
                        </Box>
                        <Typography
                          sx={{
                            fontFamily: FONT,
                            fontWeight: 700,
                            fontSize: 13.5,
                            lineHeight: 1.3,
                            color: INK,
                            minWidth: 0,
                            overflowWrap: "anywhere",
                          }}
                        >
                          {op.name}
                        </Typography>
                        {isSelected && (
                          <CheckCircleIcon
                            sx={{
                              position: "absolute",
                              top: -9,
                              right: 10,
                              fontSize: 22,
                              color: BRAND,
                              backgroundColor: "#fff",
                              borderRadius: "50%",
                            }}
                          />
                        )}
                      </Box>
                    );
                  })}
                </Box>
              )}
            </Box>
          </Collapse>

          {/* ---- Step 3: amount ---- */}
          <Collapse in={numberValid && !!operator} unmountOnExit>
            <Box sx={{ mt: 3.5 }}>
              <PanelHead icon="₹" title="Recharge amount" />

              <TextField
                fullWidth
                value={amount}
                onChange={(e) => setAmount(e.target.value.replace(/\D/g, "").slice(0, 5))}
                placeholder="Enter amount"
                autoComplete="off"
                error={amountTooLow}
                helperText={amountTooLow ? `Minimum recharge amount is ₹${MIN_AMOUNT}` : ""}
                inputProps={{
                  inputMode: "numeric",
                  maxLength: 5,
                  "aria-label": "Recharge amount",
                  style: {
                    fontSize: 22,
                    fontWeight: 800,
                    fontVariantNumeric: "tabular-nums",
                    padding: "14px 4px",
                  },
                }}
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start" sx={{ ml: 1 }}>
                      <Typography sx={{ fontFamily: FONT, fontWeight: 800, fontSize: 22, color: MUTED }}>
                        ₹
                      </Typography>
                    </InputAdornment>
                  ),
                  endAdornment: amount ? (
                    <InputAdornment position="end">
                      <IconButton
                        size="small"
                        aria-label="Clear amount"
                        onClick={() => setAmount("")}
                        sx={{ color: FAINT, "&:hover": { color: MUTED } }}
                      >
                        <CancelIcon fontSize="small" />
                      </IconButton>
                    </InputAdornment>
                  ) : null,
                }}
                sx={fieldSx}
              />

              <Box sx={{ display: "flex", flexWrap: "wrap", gap: 1, mt: 1.6 }}>
                {QUICK_AMOUNTS.map((v) => {
                  const active = amountNum === v;
                  return (
                    <Box
                      key={v}
                      component="button"
                      type="button"
                      onClick={() => setAmount(String(v))}
                      sx={{
                        cursor: "pointer",
                        border: `1.5px solid ${active ? BRAND : "transparent"}`,
                        fontFamily: FONT,
                        fontWeight: 700,
                        fontSize: 13.5,
                        px: 1.8,
                        py: 0.7,
                        borderRadius: "12px",
                        backgroundColor: active ? BRAND_SOFT : "#fff",
                        color: active ? BRAND : INK,
                        boxShadow: SOFT_SHADOW,
                        transition: "border-color .15s, background-color .15s",
                        "&:hover": { backgroundColor: BRAND_SOFT },
                        "&:focus-visible": { outline: `2px solid ${BRAND}`, outlineOffset: 2 },
                      }}
                    >
                      ₹{v}
                    </Box>
                  );
                })}
              </Box>

              <Typography
                sx={{
                  display: "flex",
                  alignItems: "flex-start",
                  gap: 0.8,
                  mt: 1.6,
                  fontFamily: FONT,
                  fontWeight: 500,
                  fontSize: 13,
                  lineHeight: 1.45,
                  color: MUTED,
                }}
              >
                <InfoOutlinedIcon sx={{ fontSize: 16, mt: "1px", flexShrink: 0 }} />
                Enter the exact amount you want to recharge, or tap a quick amount.
              </Typography>
            </Box>
          </Collapse>
        </Box>

        {/* ================= RIGHT: summary + pay ================= */}
        <Box sx={{ ...panelSx, position: { lg: "sticky" }, top: { lg: 16 } }}>
          <PanelHead icon={<ReceiptLongOutlinedIcon />} title="Recharge summary" />

          <Box sx={{ display: "grid", gap: 1.4 }}>
            <InfoTile tint="blue" label="Mobile number" value={numberValid ? `+91 ${number}` : ""} />
            <InfoTile tint="green" label="Operator" value={operator?.name} logo={operator?.logo_url} />
          </Box>

          <Box
            sx={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              mt: 2.2,
              pt: 2,
              borderTop: "1.5px dashed #c9d5ee",
            }}
          >
            <Typography sx={{ fontFamily: FONT, fontWeight: 700, fontSize: 15, color: INK }}>
              Amount to pay
            </Typography>
            <Typography
              sx={{
                fontFamily: FONT,
                fontWeight: 800,
                fontSize: 28,
                color: amountValid ? BRAND : FAINT,
                fontVariantNumeric: "tabular-nums",
              }}
            >
              ₹{amountValid ? amountNum : 0}
            </Typography>
          </Box>

          {/* ---- Step 4: pay ---- */}
          <Button
            fullWidth
            disableElevation
            disabled={!canProceed}
            onClick={onProceed}
            startIcon={canProceed ? <LockOutlinedIcon sx={{ fontSize: 20 }} /> : null}
            sx={{
              mt: 2.4,
              py: 1.7,
              borderRadius: "16px",
              textTransform: "none",
              fontFamily: FONT,
              fontWeight: 700,
              fontSize: 16,
              color: "#fff",
              backgroundColor: BRAND,
              boxShadow: canProceed ? "0 12px 24px -8px rgba(30,86,224,0.6)" : "none",
              "&:hover": { backgroundColor: BRAND_DARK },
              "&.Mui-disabled": { backgroundColor: "#e4eaf6", color: "#8a97b1" },
            }}
          >
            {ctaLabel}
          </Button>

          <Typography
            sx={{
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              gap: 0.7,
              mt: 1.8,
              fontFamily: FONT,
              fontWeight: 500,
              fontSize: 13,
              color: MUTED,
            }}
          >
            <LockOutlinedIcon sx={{ fontSize: 15 }} />
            Secure payment. You&apos;ll confirm with your TPIN next.
          </Typography>
        </Box>
      </Box>
    </Box>
  );
};

export default MobileRechargeCard;